<header class="dashboard-page-header"><div><p class="dashboard-kicker"><i class="ph ph-pencil-simple" aria-hidden="true"></i><span>Email operations</span></p><h1>Create campaign</h1><p>Draft plain, useful copy. Queueing remains a separate explicit action.</p></div><a class="button button--quiet" href="/admin/newsletter">Back to campaigns</a></header><form class="dashboard-panel mt-8 grid gap-5" action="/admin/newsletter" method="post" novalidate><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><div class="field-group"><label for="campaign-subject">Subject</label><input id="campaign-subject" name="subject" maxlength="180" value="<?= old_value($old, 'subject') ?>" required aria-describedby="campaign-subject-help<?= field_error($errors, 'subject') ? ' campaign-subject-error' : '' ?>"<?= field_error($errors, 'subject') ? ' aria-invalid="true"' : '' ?>><p id="campaign-subject-help" class="field-help">3 to 180 characters.</p><?php if ($error = field_error($errors, 'subject')): ?><p id="campaign-subject-error" class="field-error" role="alert"><?= e($error) ?></p><?php endif; ?></div><div class="field-group"><label for="campaign-message">Message</label><textarea id="campaign-message" name="message" rows="10" maxlength="4000" required aria-describedby="campaign-message-help<?= field_error($errors, 'message') ? ' campaign-message-error' : '' ?>"<?= field_error($errors, 'message') ? ' aria-invalid="true"' : '' ?>><?= old_value($old, 'message') ?></textarea><p id="campaign-message-help" class="field-help">10 to 4000 characters. Every delivery includes an unsubscribe link.</p><?php if ($error = field_error($errors, 'message')): ?><p id="campaign-message-error" class="field-error" role="alert"><?= e($error) ?></p><?php endif; ?></div><button class="button button--primary" type="submit">Save draft</button></form>
